@Transactional
public void updateAccountBalance(Long accountId, BigDecimal newBalance) {
    EntityManager em = entityManagerFactory.createEntityManager();
    em.setFlushMode(FlushModeType.COMMIT);

    try {
        Account account = em.find(Account.class, accountId);
        account.setBalance(newBalance);
        // Dirty checking flags 'account' as modified.
        // Because FlushMode is COMMIT, em.flush() is not triggered by subsequent queries here.

        em.getTransaction().commit(); // SQL UPDATE fires here synchronously.
    } finally {
        em.close();
    }
}
